<script lang="ts">
  import type { PageData } from './$types';
  import { createBrowserClient } from '@supabase/ssr';
  import { PUBLIC_SUPABASE_URL, PUBLIC_SUPABASE_PUBLISHABLE_KEY } from '$env/static/public';
  import { invalidateAll } from '$app/navigation';
  import { Search, Plus, CheckCircle2, ArrowLeftRight, X } from 'lucide-svelte';
  export let data: PageData;
  const supabase = createBrowserClient(PUBLIC_SUPABASE_URL, PUBLIC_SUPABASE_PUBLISHABLE_KEY);
  let query='', modal=false, busy=false, message='', error='';
  let form={book_id:'',borrower_id:'',borrowed_at:new Date().toISOString().slice(0,10),due_date:new Date(Date.now()+14*86400000).toISOString().slice(0,10),notes:''};
  $: filtered=data.loans.filter((l)=>[l.books?.title,l.borrowers?.full_name,l.borrowers?.student_id].some((v)=> (v??'').toLowerCase().includes(query.toLowerCase())));
  function openNew(){form={book_id:'',borrower_id:'',borrowed_at:data.today,due_date:new Date(Date.now()+14*86400000).toISOString().slice(0,10),notes:''};error='';message='';modal=true;}
  async function issue(){
    busy=true;error='';message='';
    const {error:e}=await supabase.rpc('issue_book',{p_book_id:form.book_id,p_borrower_id:form.borrower_id,p_borrowed_at:form.borrowed_at,p_due_date:form.due_date,p_notes:form.notes.trim()||null});
    busy=false;
    if(e){error=e.message;return;}
    modal=false;message='Book issued successfully.';await invalidateAll();
  }
  async function returnBook(loan: PageData['loans'][number]){
    if(!confirm(`Record "${loan.books?.title}" as returned by ${loan.borrowers?.full_name}?`))return;
    error='';message='';
    const {error:e}=await supabase.rpc('return_book',{p_borrowing_id:loan.id});
    if(e){error=e.message;return;}
    message='Book return recorded.';await invalidateAll();
  }
  function status(l: PageData['loans'][number]){if(l.returned_at)return 'Returned';return l.due_date<data.today?'Overdue':'Borrowed';}
</script>

<div class="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="text-sm font-semibold text-indigo-600">CIRCULATION</p><h1 class="mt-1 text-3xl font-bold tracking-tight text-slate-900">Borrowing records</h1><p class="mt-2 text-sm text-slate-500">Issue books and record returns.</p></div><button on:click={openNew} class="inline-flex items-center justify-center gap-2 rounded-xl bg-indigo-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-indigo-700"><Plus size={17}/> Issue a book</button></div>
{#if message}<div class="mb-4 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-800">{message}</div>{/if}
{#if error || data.errors.length}<div class="mb-4 rounded-xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-700">{error || data.errors.join('; ')}</div>{/if}
<div class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="flex flex-col gap-3 border-b border-slate-100 p-4 sm:flex-row sm:items-center sm:justify-between"><div><h2 class="font-bold text-slate-900">Loan history</h2><p class="mt-1 text-xs text-slate-500">{filtered.length} transaction(s)</p></div><div class="relative w-full sm:max-w-xs"><Search size={17} class="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input bind:value={query} placeholder="Search book or borrower..." class="w-full rounded-xl border border-slate-200 py-2.5 pl-9 pr-3 text-sm outline-none focus:border-indigo-500"/></div></div>
{#if filtered.length}<div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-5 py-3">Book / borrower</th><th class="px-5 py-3">Borrowed</th><th class="px-5 py-3">Due date</th><th class="px-5 py-3">Status</th><th class="px-5 py-3 text-right">Action</th></tr></thead><tbody class="divide-y divide-slate-100">{#each filtered as l}<tr class="hover:bg-slate-50/70"><td class="px-5 py-4"><div class="font-semibold text-slate-800">{l.books?.title??'Unknown book'}</div><div class="mt-1 text-xs text-slate-500">{l.borrowers?.full_name??'Unknown borrower'}{#if l.borrowers?.student_id} · {l.borrowers.student_id}{/if}</div></td><td class="px-5 py-4 text-slate-600">{l.borrowed_at}</td><td class="px-5 py-4 text-slate-600">{l.due_date}</td><td class="px-5 py-4">{#if status(l)==='Returned'}<span class="rounded-full bg-emerald-50 px-2.5 py-1 text-xs font-semibold text-emerald-700">Returned</span>{:else if status(l)==='Overdue'}<span class="rounded-full bg-rose-50 px-2.5 py-1 text-xs font-semibold text-rose-700">Overdue</span>{:else}<span class="rounded-full bg-amber-50 px-2.5 py-1 text-xs font-semibold text-amber-700">Borrowed</span>{/if}</td><td class="px-5 py-4 text-right">{#if !l.returned_at}<button on:click={()=>returnBook(l)} class="inline-flex items-center gap-1.5 rounded-lg border border-emerald-200 px-3 py-2 text-xs font-semibold text-emerald-700 hover:bg-emerald-50"><CheckCircle2 size={15}/> Return</button>{:else}<span class="text-xs text-slate-400">Returned {l.returned_at.slice(0,10)}</span>{/if}</td></tr>{/each}</tbody></table></div>{:else}<div class="p-12 text-center"><ArrowLeftRight class="mx-auto h-9 w-9 text-slate-300"/><h3 class="mt-3 font-semibold text-slate-800">No borrowing records</h3><p class="mt-1 text-sm text-slate-500">Issue a book to create the first transaction.</p></div>{/if}</div>

{#if modal}<div class="fixed inset-0 z-50 grid place-items-center bg-slate-950/40 p-4" role="presentation" on:click={(e)=>{if(e.target===e.currentTarget)modal=false;}}><div role="dialog" aria-modal="true" class="w-full max-w-xl rounded-2xl bg-white p-6 shadow-xl"><div class="mb-5 flex items-center justify-between"><div><h2 class="text-xl font-bold text-slate-900">Issue a book</h2><p class="mt-1 text-sm text-slate-500">Choose a book, borrower, and due date.</p></div><button on:click={()=>modal=false} class="rounded-lg p-2 text-slate-500 hover:bg-slate-100"><X size={19}/></button></div>{#if error}<div class="mb-4 rounded-lg bg-rose-50 p-3 text-sm text-rose-700">{error}</div>{/if}<form on:submit|preventDefault={issue} class="space-y-4"><div><label for="issue-book" class="mb-1.5 block text-sm font-semibold">Book *</label><select id="issue-book" bind:value={form.book_id} required class="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5"><option value="" disabled>Select a book</option>{#each data.books as b}<option value={b.id}>{b.title} — {b.author} ({b.total_copies} total copies)</option>{/each}</select></div><div><label for="issue-borrower" class="mb-1.5 block text-sm font-semibold">Borrower *</label><select id="issue-borrower" bind:value={form.borrower_id} required class="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5"><option value="" disabled>Select a borrower</option>{#each data.borrowers as b}<option value={b.id}>{b.full_name}{b.student_id?' — '+b.student_id:''}</option>{/each}</select></div><div class="grid gap-4 sm:grid-cols-2"><div><label for="borrowed-date" class="mb-1.5 block text-sm font-semibold">Borrowed date *</label><input id="borrowed-date" type="date" bind:value={form.borrowed_at} required class="w-full rounded-xl border border-slate-200 px-3 py-2.5"/></div><div><label for="due-date" class="mb-1.5 block text-sm font-semibold">Due date *</label><input id="due-date" type="date" min={form.borrowed_at} bind:value={form.due_date} required class="w-full rounded-xl border border-slate-200 px-3 py-2.5"/></div></div><div><label for="issue-notes" class="mb-1.5 block text-sm font-semibold">Notes (optional)</label><textarea id="issue-notes" bind:value={form.notes} rows="2" maxlength="1000" class="w-full rounded-xl border border-slate-200 px-3 py-2.5 outline-none focus:border-indigo-500"></textarea></div><p class="rounded-lg bg-indigo-50 p-3 text-xs leading-5 text-indigo-800">The database checks availability at the moment of issue and prevents borrowing if no copies remain.</p><div class="flex justify-end gap-3 border-t border-slate-100 pt-4"><button type="button" on:click={()=>modal=false} class="rounded-xl border border-slate-200 px-4 py-2.5 text-sm font-semibold">Cancel</button><button disabled={busy || !data.books.length || !data.borrowers.length} class="rounded-xl bg-indigo-600 px-5 py-2.5 text-sm font-semibold text-white disabled:opacity-50">{busy?'Processing…':'Confirm borrowing'}</button></div></form></div></div>{/if}
